"use client";

import React, { useMemo } from "react";
import katex from "katex";

/** Renders LaTeX generated by our own model (never user-supplied strings); \htmlClass is the only trusted command. */
export function MathDisplay({ latex, className, label }: { latex: string; className?: string; label?: string }) {
  const html = useMemo(() => {
    try {
      return katex.renderToString(latex || "\\ ", { throwOnError: false, output: "html", trust: (c) => c.command === "\\htmlClass" });
    } catch {
      return "";
    }
  }, [latex]);
  return <span className={className} role="img" aria-label={label} dangerouslySetInnerHTML={{ __html: html }} />;
}
